-- The Sample Institute is the original techcadd data: its look moves from the code into its own branding row
-- (Phase 3: the code is neutral; an institute's identity is its data). Only where it has not set its own.
UPDATE organisations SET
  legal_name = coalesce(legal_name, 'techcadd Computer Education'),
  branding = '{"tagline": "Your Skill & Technology Partner", "color": "#10186a", "logo": "data:image/png;base64,", "accreditations": "data:image/png;base64,"}'::jsonb || branding
WHERE id = '00000000-0000-4000-8000-000000000001' AND NOT (branding ? 'logo');
